import {McpServer} from "@modelcontextprotocol/sdk/server/mcp.js";
import {z} from "zod";
import {Base} from "./schema.js";
import {operation} from "./logic.js";
const Schema=Base.extend({path:z.string().min(1).optional().default(".")}).shape;
const server=new McpServer({name:"unit",version:"1"});
server.tool("initialize","Initialize",Schema,args=>operation(args));

